=== AGENTS.md
     1	# reports-service agent guide
     2	
     3	- Runtime: Bun, deployed to Cloud Run with `./deploy.sh`. Run the tests with `bun test`.
     4	- Layout: `src/app.ts` holds the HTTP handlers, `src/db.ts` persistence, `src/llm.ts` the model-API client.
     5	- Keep modules small and single-purpose. No new runtime dependencies without a reason.
=== Dockerfile
     1	FROM oven/bun:1
     2	WORKDIR /app
     3	COPY package.json ./
     4	COPY src ./src
     5	ENV PORT=8080
     6	CMD ["bun", "src/app.ts"]
=== deploy.sh
     1	#!/usr/bin/env bash
     2	set -euo pipefail
     3	gcloud run deploy reports-service --source . --region us-central1 --allow-unauthenticated
=== package.json
     1	{
     2	  "name": "reports-service",
     3	  "version": "0.1.0",
     4	  "type": "module",
     5	  "private": true,
     6	  "scripts": {
     7	    "test": "bun test",
     8	    "start": "bun src/app.ts"
     9	  }
    10	}
=== src/app.ts
     1	import { getReport, saveReport } from "./db";
     2	
     3	const json = (body: unknown, status = 200) =>
     4	  new Response(JSON.stringify(body), {
     5	    status,
     6	    headers: { "content-type": "application/json" },
     7	  });
     8	
     9	export async function handle(req: Request): Promise<Response> {
    10	  const url = new URL(req.url);
    11	  const getMatch = url.pathname.match(/^\/reports\/([^/]+)$/);
    12	  if (req.method === "GET" && getMatch) {
    13	    const report = getReport(getMatch[1]);
    14	    return report ? json(report) : json({ error: "not found" }, 404);
    15	  }
    16	  const shareMatch = url.pathname.match(/^\/reports\/([^/]+)\/share$/);
    17	  if (req.method === "POST" && shareMatch) {
    18	    const report = getReport(shareMatch[1]);
    19	    if (!report) return json({ error: "not found" }, 404);
    20	    saveReport({ ...report, shared: true });
    21	    return json({ shared: true });
    22	  }
    23	  return json({ error: "not found" }, 404);
    24	}
    25	
    26	if (import.meta.main) {
    27	  Bun.serve({ port: Number(process.env.PORT ?? 8080), fetch: handle });
    28	}
=== src/db.ts
     1	export type Report = {
     2	  id: string;
     3	  company: string;
     4	  sections: string[];
     5	  title: string | null;
     6	  shared: boolean;
     7	};
     8	
     9	const reports = new Map<string, Report>();
    10	
    11	export function getReport(id: string): Report | undefined {
    12	  return reports.get(id);
    13	}
    14	
    15	export function saveReport(report: Report): void {
    16	  reports.set(report.id, report);
    17	}
    18	
    19	export function listSavedReports(): Report[] {
    20	  return [...reports.values()];
    21	}
=== src/llm.ts
     1	// Takes 20-60 s per call and costs money per call.
     2	export async function generateSection(
     3	  company: string,
     4	  section: string,
     5	): Promise<string> {
     6	  const res = await fetch("https://api.example-llm.com/v1/generate", {
     7	    method: "POST",
     8	    body: JSON.stringify({ prompt: `Write the "${section}" section for ${company}` }),
     9	  });
    10	  return (await res.json()).text as string;
    11	}
    12	
    13	// Takes 1-3 s per call and costs money per call.
    14	export async function suggestTitle(sections: string[]): Promise<string> {
    15	  const res = await fetch("https://api.example-llm.com/v1/title", {
    16	    method: "POST",
    17	    body: JSON.stringify({ sections }),
    18	  });
    19	  return (await res.json()).title as string;
    20	}
