{
  "version": 1,
  "excluded": [
    {
      "id": "in-process-nightly-timer",
      "path": "Run the nightly refresh from a setInterval/cron timer inside the existing reports-service process",
      "reason": "Cloud Run request-based billing throttles CPU outside requests and scales instances to zero, so a timer never fires reliably and in-flight paid work is killed on SIGTERM (10 s grace) — https://docs.cloud.google.com/run/docs/configuring/billing-settings; the flow-system-design execution-model table lists timers as job runners under Never"
    },
    {
      "id": "generate-inside-scheduler-tick",
      "path": "Have the Cloud Scheduler tick regenerate every report itself in one long request",
      "reason": "one section call takes 20-60 s (src/llm.ts:1), so even a few reports outrun the tick's attempt deadline, and one failure would re-run every report; the scheduler tick must only enqueue one task per unit"
    },
    {
      "id": "one-task-per-section-fan-in",
      "path": "Enqueue one Cloud Task per section with a parent status row and a finalize step",
      "reason": "the retry savings it buys are already captured by staging each finished section on the report record and skipping it on retry; it adds a fan-in finalize task and multiplies task volume by the section count for no user-visible gain"
    }
  ]
}
